Q: TableLayoutPanel displays vertical scroll A: <p><a href="https://i.sstatic.net/JBmSs92C.png" rel="nofollow noreferrer"><img src="https://i.sstatic.net/JBmSs92C.png" alt="enter image description here" /></a>Biouk's answer is good, but in my case I wanted the <code>TableLayoutPanel</code> to be able to grow in height so that the rows would expand to available height. In my specific case, I wanted a multiline textbox at the bottom to grow in height. If the <code>TableLayoutPanel</code> is docked to the <code>Top</code> of the form then its height doesn't expand. The solution is to write a simple custom <code>LayoutEngine</code>:</p>
<pre class="lang-cs prettyprint-override"><code>
private class MyPanel : Panel {

    LayoutEngine le = new MyLayoutEngine(); // custom layout engine
    public MyPanel() {}

    public override LayoutEngine LayoutEngine {
        get {
            return le;
        }
    }

    private class MyLayoutEngine : LayoutEngine {
        public override void InitLayout(object child, BoundsSpecified specified) {}
        public override bool Layout(object container, LayoutEventArgs layoutEventArgs) {
            var c = (MyPanel) container;
            if (c.Controls.Count == 0) return true;
            Size sz = c.ClientSize;
            var panel = c.Controls[0];
            Size ps = panel.GetPreferredSize(sz);
            int h = sz.Height - 3; // not sure why - 3 but it's required to
            int w = sz.Width - 3; // to stop the scrollbars from briefly appearing on and off
            if (h &lt; ps.Height) {
                // not allowing the panel's height to be less than its preferred height forces the
                // vertical scrollbar to appear
                h = ps.Height;
                // if the scrollbar is not visible then it will be, so the width has
                // to be reduced to prevent the horizontal scrollbar from appearing.
                if (!c.VerticalScroll.Visible)
                    w = w - SystemInformation.VerticalScrollBarWidth;
            }

            panel.SetBounds(0, 0, w, h);
            return true;
        }
    }
}

    Form ff = new Form { Size = new Size(800, 800) };
    TextBox tbNotes = new TextBox { Multiline = true, Dock = DockStyle.Fill, ReadOnly = true };
    TableLayoutPanel panel = new TableLayoutPanel { Dock = DockStyle.Left };
    panel.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));
    panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 1f));
    panel.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 1f));
    panel.SetColumnSpan(tbNotes, 2);
    int row = 0;
    for (; row &lt; 10; row++) {
        panel.Controls.Add(new Label { Text = &quot;Label&quot; + row, AutoSize = true, Anchor = AnchorStyles.None }, 0, row);
        panel.Controls.Add(new TextBox { Dock = DockStyle.Fill }, 1, row);
        panel.Controls.Add(new TextBox { Dock = DockStyle.Fill }, 2, row);
    }
    panel.Controls.Add(new Label { Text = &quot;Notes&quot;, AutoSize = true, Anchor = AnchorStyles.None }, 0, row);
    panel.Controls.Add(tbNotes, 1, row);

    MyPanel hostPanel = new MyPanel { Dock = DockStyle.Fill, AutoScroll = true }; // custom panel
    hostPanel.Controls.Add(panel);

    ff.Controls.Add(hostPanel);
</code></pre>

Q: Option &#39;baseUrl&#39; is deprecated and will stop functioning in TypeScript 7 A: <p><code>baseUrl</code> will no longer be supported in Typescript 7.0 as explained in this <a href="https://github.com/microsoft/TypeScript/issues/62207" rel="nofollow noreferrer">related Github post</a> by Daniel Rosenwasser.</p>
<p>To fix the error, explicitly include the full path in your paths mappings. As an example, instead of</p>
<pre><code>// old file with baseUrl
{
  &quot;compilerOptions&quot;: {
    &quot;baseUrl&quot;: &quot;./src&quot;,
    &quot;paths&quot;: {
      &quot;@app/*&quot;: [&quot;app/*&quot;],
      &quot;@lib/*&quot;: [&quot;lib/*&quot;]
    }
  }
}
</code></pre>
<p>remove <code>baseUrl</code>, and the paths should become:</p>
<pre><code>&quot;paths&quot;: {
  // add ./src from baseUrl
  &quot;@app/*&quot;: [&quot;./src/app/*&quot;],
  &quot;@lib/*&quot;: [&quot;./src/lib/*&quot;]
}
</code></pre>
